using BUS;
using ET;
namespace RangHamMat.ClinicalChecks;
internal static class DonThuocChecks
{
    internal static void Need(bool ok,string text)=>KhamVaKeHoachChecks.Need(ok,text);
    private static void Invalid(Action action)=>Throws<LoiKhamException>(action);
    private static void Denied(Action action)=>Throws<TuChoiQuyenNghiepVuException>(action);
    private static void Throws<T>(Action action)where T:Exception{try{action();}catch(T){return;}throw new Exception("Phải chặn bằng "+typeof(T).Name);}
    internal static YeuCauLuuDon Request(Fixture f,int count=3)=>new(){MaLS=f.Id("LSA"),CacDong=f.Connection.QueryDrugIds(f.Transaction,count).Select(d=>new DongThuocKeDon {MaThuoc=d,LieuDung="FIXTURE liều",DuongDung="FIXTURE đường",HuongDan="FIXTURE không dùng thật",SoNgayDung=2,SoLuong=3}).ToArray()};
    internal static YeuCauLuuDon Update(BanNhapDon s)=>new(){MaDT=s.Don.MaDT,MaLS=s.Don.MaLS,MaDTThayThe=s.Don.MaDTThayThe,LyDoThayThe=s.Don.LyDoThayThe,GhiChu=s.Don.GhiChu,DauVanTay=s.DauVanTay,CacDong=s.CacDong.Select(d=>new DongThuocKeDon{MaCTDT=d.MaCTDT,MaThuoc=d.MaThuoc,LieuDung=d.LieuDung,DuongDung=d.DuongDung??"",HuongDan=d.HuongDan,SoNgayDung=d.SoNgayDung,SoLuong=d.SoLuong,PhienBanHuongDan=d.PhienBanHuongDan,DaXacNhanPhuHop=d.PhienBanHuongDan is not null}).ToArray()};
    internal static void Complete(Fixture f,NguCanhNghiepVu u)
    {var b=new BUS_KHAMDIEUTRI(f.Transaction);var c=b.LuuKham(KhamVaKeHoachChecks.Request(b.LayBanNhap(f.Id("LSA"),u)),u);b.HoanTatKham(f.Id("LSA"),c.DauVanTay,u);}
    internal static IEnumerable<(string,Action<Fixture>)> Cases()=>RawCases().Select(c=>(c.Item1,(Action<Fixture>)(f=>{f.Execute("DELETE dbo.CHI_TIET_DON_THUOC WHERE MaDT=@id;DELETE dbo.DON_THUOC WHERE MaDT=@id",new{id=f.Id("DTA")});c.Item2(f);})));
    private static IEnumerable<(string,Action<Fixture>)> RawCases()
    {
        yield return("RX07: Hàm lượng đổi sau lưu không âm thầm đổi nguồn khi ký",f=>
        {var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f,1),a);f.Execute("UPDATE dbo.THUOC SET HamLuong=N'FIXTURE hàm lượng đã đổi' WHERE MaThuoc=@id",new{id=s.CacDong[0].MaThuoc});Throws<XungDotDuLieuKhamException>(()=>b.XacNhanDon(s.Don.MaDT,s.DauVanTay,a));Need(b.LayBanNhapDon(s.Don.MaDT,a).Don.TrangThai=="Nháp","Ký chỉ định theo hàm lượng tự đổi");});
        yield return("RX07: Hai nháp tạo trước không được ký bổ sung thiếu lý do",f=>
        {var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var first=b.LuuDon(Request(f,1),a);var second=b.LuuDon(Request(f,1),a);b.XacNhanDon(first.Don.MaDT,first.DauVanTay,a);Invalid(()=>b.XacNhanDon(second.Don.MaDT,second.DauVanTay,a));Need(b.LayBanNhapDon(second.Don.MaDT,a).Don.TrangThai=="Nháp","Ký thêm không có lý do");});
        yield return("RX07: Sửa đơn bổ sung không được xóa lý do trước ký",f=>
        {var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var first=b.LuuDon(Request(f,1),a);b.XacNhanDon(first.Don.MaDT,first.DauVanTay,a);var second=b.LuuDon(Request(f,1) with {GhiChu="FIXTURE bổ sung"},a);Invalid(()=>b.LuuDon(Update(second) with {GhiChu=""},a));Need(b.LayBanNhapDon(second.Don.MaDT,a).Don.GhiChu=="FIXTURE bổ sung","Lý do cũ đã mất");});
        yield return("RX07: Không gian trước ký và bản in có ngày sinh cùng thông tin an toàn",f=>
        {f.Execute("UPDATE dbo.BENH_NHAN SET NgaySinh='1990-01-02',DiUng=N'FIXTURE dị ứng',TienSuBenh=N'FIXTURE tiền sử' WHERE MaBN=@id",new{id=f.Id("BN1")});var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var space=b.LayKhongGianKeDon(f.Id("LSA"),a);Need(space.GetType().GetProperty("NgaySinh")?.GetValue(space) is DateTime d&&d==new DateTime(1990,1,2),"Thiếu DOB trước ký");Need((string?)space.GetType().GetProperty("DiUng")?.GetValue(space)=="FIXTURE dị ứng","Thiếu nhắc dị ứng");var s=b.LuuDon(Request(f,1),a);s=b.XacNhanDon(s.Don.MaDT,s.DauVanTay,a);var print=b.LayBanInDon(s.Don.MaDT,a);Need(print.GetType().GetProperty("NgaySinh")?.GetValue(print) is DateTime dob&&dob==new DateTime(1990,1,2),"Bản in thiếu DOB");});
        yield return("RX07: Chèn dòng mới trước các mã dòng cũ không cấp trùng khóa",f=>
        {var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f,2),a);var next=Request(f,3).CacDong[2];var r=Update(s) with {CacDong=new[]{next}.Concat(Update(s).CacDong).ToArray()};var saved=b.LuuDon(r,a);Need(saved.CacDong.Count==3&&saved.CacDong.Select(d=>d.MaCTDT).Distinct().Count()==3,"Trùng khóa sau đổi thứ tự dòng");});
        yield return("RX07: Hướng dẫn đổi phiên bản không sửa đơn ký và chặn ký nháp cũ",f=>
        {var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var r=Request(f,1);var id=r.CacDong[0].MaThuoc;var c=b.LuuHuongDan(new(){MaThuoc=id,PhienBan=1,TrangThai="Nháp",DoiTuongApDung="FIXTURE",DuongDung="FIXTURE",LieuDungGoiY="FIXTURE",HuongDanGoiY="FIXTURE"},null,a);c=b.DuyetHuongDan(id,c.DauVanTay,a);r.CacDong[0].PhienBanHuongDan=1;r.CacDong[0].DaXacNhanPhuHop=true;var old=b.LuuDon(r,a);old=b.XacNhanDon(old.Don.MaDT,old.DauVanTay,a);var pending=b.LuuDon(r with {GhiChu="FIXTURE bổ sung"},a);b.LuuHuongDan(new(){MaThuoc=id,PhienBan=2,TrangThai="Nháp",DoiTuongApDung="FIXTURE mới",DuongDung="FIXTURE",LieuDungGoiY="FIXTURE",HuongDanGoiY="FIXTURE"},c.DauVanTay,a);Invalid(()=>b.XacNhanDon(pending.Don.MaDT,pending.DauVanTay,a));Need(b.LayBanNhapDon(old.Don.MaDT,a).CacDong.Single().PhienBanHuongDan==1,"Phiên bản cũ bị đổi");});
        yield return("RX07: Nhiều đơn hiệu lực độc lập và lý do bổ sung bắt buộc",f=>
        {var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var old=b.LuuDon(Request(f,1),a);b.XacNhanDon(old.Don.MaDT,old.DauVanTay,a);Invalid(()=>b.LuuDon(Request(f,1),a));var next=b.LuuDon(Request(f,1) with {GhiChu="FIXTURE chỉ định bổ sung có lý do"},a);b.XacNhanDon(next.Don.MaDT,next.DauVanTay,a);Need(f.Scalar<int>("SELECT COUNT(*) FROM dbo.DON_THUOC WHERE MaLS=@id AND TrangThai=N'Đã xác nhận'",new{id=f.Id("LSA")})==2,"Bỏ sót/thu hồi đơn bổ sung");});
        yield return("RX07: Đơn đã xuất ghi sổ không được thay và chỉ có xuất mới đổi tồn",f=>
        {var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f,1),a);s=b.XacNhanDon(s.Don.MaDT,s.DauVanTay,a);var stock=f.Scalar<decimal>("SELECT SUM(SoLuongTon) FROM dbo.VW_TON_KHO");f.Execute("DECLARE @hh nvarchar(50)=(SELECT MaHH FROM dbo.THUOC WHERE MaThuoc=@drug);DECLARE @lo nvarchar(50)=(SELECT TOP(1) MaLo FROM dbo.LO_HANG_HOA WHERE MaHH=@hh AND TrangThai=N'Còn sử dụng' ORDER BY HanSuDung);INSERT dbo.PHIEU_XUAT(MaPX,MaKho,MaNV,MaLS,NgayXuat,LyDo,TrangThai) SELECT @px,MaKho,@nv,@ls,SYSDATETIME(),N'FIXTURE',N'Nháp' FROM dbo.LO_HANG_HOA WHERE MaLo=@lo;INSERT dbo.CHI_TIET_PHIEU_XUAT(MaCTPX,MaPX,MaHH,MaLo,MaCTDT,SoLuong,GhiChu) VALUES(@ct,@px,@hh,@lo,@line,3,N'FIXTURE');UPDATE dbo.PHIEU_XUAT SET TrangThai=N'Đã ghi sổ' WHERE MaPX=@px",new{drug=s.CacDong[0].MaThuoc,line=s.CacDong[0].MaCTDT,px=f.Id("PX07"),ct=f.Id("CTPX07"),nv=f.Id("P"),ls=f.Id("LSA")});Need(f.Scalar<decimal>("SELECT SUM(SoLuongTon) FROM dbo.VW_TON_KHO")==stock-3,"Xuất không đối chiếu tồn đúng");Invalid(()=>b.LuuDon(Request(f,1) with {MaDTThayThe=s.Don.MaDT,LyDoThayThe="FIXTURE"},a));});
        yield return("RX07: Lưu ba thuốc và ký snapshot không thay tồn",f=>{var u=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var stock=f.Scalar<decimal>("SELECT SUM(SoLuongTon) FROM dbo.VW_TON_KHO");var s=b.LuuDon(Request(f),u);Need(s.CacDong.Count==3&&s.Don.MaBS==u.MaNV&&s.Don.TrangThai=="Nháp","Thiếu dòng/actor");s=b.XacNhanDon(s.Don.MaDT,s.DauVanTay,u);Need(s.CacDong.All(d=>!string.IsNullOrWhiteSpace(d.TenThuocChot)&&!string.IsNullOrWhiteSpace(d.HamLuongChot)&&!string.IsNullOrWhiteSpace(d.DonViTinhChot)),"Thiếu chốt");Need(f.Scalar<decimal>("SELECT SUM(SoLuongTon) FROM dbo.VW_TON_KHO")==stock,"Kê/ký đã trừ kho");});
        yield return("RX07: Trùng thuốc, lượng/ngày/liều/hướng dẫn thiếu không lưu đơn",f=>{var u=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var r=Request(f);r.CacDong[2].MaThuoc=r.CacDong[0].MaThuoc;Invalid(()=>b.LuuDon(r,u));r=Request(f);r.CacDong[2].SoNgayDung=0;Invalid(()=>b.LuuDon(r,u));r=Request(f);r.CacDong[2].SoLuong=-1;Invalid(()=>b.LuuDon(r,u));r=Request(f);r.CacDong[2].HuongDan="";Invalid(()=>b.LuuDon(r,u));Need(f.Scalar<int>("SELECT COUNT(*) FROM dbo.DON_THUOC WHERE MaLS=@id",new{id=f.Id("LSA")})==0,"Để lại đầu đơn dở");});
        yield return("RX07: Lỗi dòng thứ ba giữ nguyên đầu và dòng cũ trong transaction ngoài",f=>{var u=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f),u);var r=Update(s) with {GhiChu="FIXTURE không được lưu"};r.CacDong[2].LieuDung="";Invalid(()=>b.LuuDon(r,u));Need(b.LayBanNhapDon(s.Don.MaDT,u).DauVanTay==s.DauVanTay,"Đã lưu dở");});
        yield return("RX07: Thuốc ngừng dùng không tìm/chọn/ký",f=>{var u=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var r=Request(f,1);var s=b.LuuDon(r,u);f.Execute("UPDATE dbo.HANG_HOA SET TrangThai=N'Ngừng sử dụng' WHERE MaHH=(SELECT MaHH FROM dbo.THUOC WHERE MaThuoc=@id)",new{id=r.CacDong[0].MaThuoc});Need(!b.TimThuoc(new(TuKhoa:r.CacDong[0].MaThuoc),u).Any(d=>d.MaThuoc==r.CacDong[0].MaThuoc),"Còn gợi ý thuốc ngừng");Invalid(()=>b.XacNhanDon(s.Don.MaDT,s.DauVanTay,u));});
        yield return("RX07: Nhóm lọc thuốc riêng; hướng dẫn nháp không gợi ý",f=>{var u=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var group=new ET_NHOMTHUOCKEDON {TenNhom="FIXTURE",TrangThai="Đang áp dụng"};new BUS_NHOMTHUOCKEDON(f.Transaction).LuuNhap(group,u);var id=Request(f,1).CacDong[0].MaThuoc;var c=b.LuuHuongDan(new(){MaThuoc=id,MaNhomThuoc=group.MaNhomThuoc,PhienBan=1,TrangThai="Nháp",DoiTuongApDung="FIXTURE",DuongDung="FIXTURE",LieuDungGoiY="FIXTURE",HuongDanGoiY="FIXTURE"},null,u);var rows=b.TimThuoc(new(MaNhomThuoc:group.MaNhomThuoc),u);Need(rows.Count==1&&rows[0].MaThuoc==id&&rows[0].HuongDan is null,"Lọc sai/lộ hướng dẫn nháp");b.DuyetHuongDan(id,c.DauVanTay,u);Need(b.TimThuoc(new(MaNhomThuoc:group.MaNhomThuoc),u).Single().HuongDan?.MaNguoiDuyet==u.MaNV,"Thiếu hướng dẫn đã duyệt");});
        yield return("RX07: Áp hướng dẫn cần xác nhận phù hợp và đúng phiên bản duyệt",f=>{var u=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var r=Request(f,1);var id=r.CacDong[0].MaThuoc;var c=b.LuuHuongDan(new(){MaThuoc=id,PhienBan=1,TrangThai="Nháp",DoiTuongApDung="FIXTURE",DuongDung="FIXTURE",LieuDungGoiY="FIXTURE",HuongDanGoiY="FIXTURE"},null,u);r.CacDong[0].PhienBanHuongDan=1;Invalid(()=>b.LuuDon(r,u));b.DuyetHuongDan(id,c.DauVanTay,u);Invalid(()=>b.LuuDon(r,u));r.CacDong[0].DaXacNhanPhuHop=true;Need(b.LuuDon(r,u).CacDong[0].PhienBanHuongDan==1,"Không lưu nguồn hướng dẫn");});
        yield return("RX07: Admin/dược sĩ soạn cấu hình, Admin không ký thay chuyên môn",f=>{var x=f.User("X");var b=new BUS_DONTHUOC(f.Transaction);var id=Request(f,1).CacDong[0].MaThuoc;var c=b.LuuHuongDan(new(){MaThuoc=id,PhienBan=1,TrangThai="Nháp",DoiTuongApDung="FIXTURE",DuongDung="FIXTURE",LieuDungGoiY="FIXTURE",HuongDanGoiY="FIXTURE"},null,x);Denied(()=>b.DuyetHuongDan(id,c.DauVanTay,x));});
        yield return("RX07: Bác sĩ khác, điều dưỡng và Admin không lưu/ký dù biết mã",f=>{var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f),a);foreach(var role in new[]{"B","N","X"}){var u=f.User(role);Denied(()=>b.LuuDon(Update(s),u));Denied(()=>b.XacNhanDon(s.Don.MaDT,s.DauVanTay,u));}});
        yield return("RX07: Snapshot cũ không ghi đè hoặc ký đơn đã đổi",f=>{var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f),a);b.LuuDon(Update(s) with {GhiChu="FIXTURE cửa sổ mới"},a);Throws<XungDotDuLieuKhamException>(()=>b.LuuDon(Update(s),a));Throws<XungDotDuLieuKhamException>(()=>b.XacNhanDon(s.Don.MaDT,s.DauVanTay,a));});
        yield return("RX07: Thay đơn sau hoàn tất, cũ chỉ ngừng khi ký mới và chặn chờ thu",f=>{var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var old=b.LuuDon(Request(f),a);old=b.XacNhanDon(old.Don.MaDT,old.DauVanTay,a);Complete(f,a);var r=Request(f,1) with {MaDTThayThe=old.Don.MaDT,LyDoThayThe="FIXTURE thay"};var next=b.LuuDon(r,a);Need(b.LayBanNhapDon(old.Don.MaDT,a).Don.TrangThai=="Đã xác nhận","Ngừng cũ quá sớm");Invalid(()=>b.KiemTraDonChoThu(f.Id("LSA"),a));b.XacNhanDon(next.Don.MaDT,next.DauVanTay,a);Need(b.LayBanNhapDon(old.Don.MaDT,a).Don.TrangThai=="Ngừng áp dụng"&&b.KiemTraDonChoThu(f.Id("LSA"),a),"Thay/chờ thu sai");});
        yield return("RX07: Một nguồn thay chỉ có một bản nháp đang soạn",f=>{var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f),a);s=b.XacNhanDon(s.Don.MaDT,s.DauVanTay,a);var r=Request(f,1) with {MaDTThayThe=s.Don.MaDT,LyDoThayThe="FIXTURE"};b.LuuDon(r,a);Invalid(()=>b.LuuDon(r,a));});
        yield return("RX07: Đã có hóa đơn thì không soạn/thay/ký đơn",f=>{var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f),a);s=b.XacNhanDon(s.Don.MaDT,s.DauVanTay,a);f.Execute("INSERT dbo.HOA_DON(MaHD,MaLS,MaNV,NgayLap,TongTien,GiamGia,TrangThai) VALUES(@id,@ls,@nv,SYSDATETIME(),0,0,N'Nháp')",new{id=f.Id("HDRX"),ls=f.Id("LSA"),nv=f.Id("R")});Invalid(()=>b.LuuDon(Request(f) with {MaDTThayThe=s.Don.MaDT,LyDoThayThe="FIXTURE"},a));});
        yield return("RX07: Không kê thuốc có lý do không tạo đơn nháp hoặc mở khóa lượt",f=>{var a=f.User("A");var clinical=new BUS_KHAMDIEUTRI(f.Transaction);var c=clinical.LuuKham(KhamVaKeHoachChecks.Request(clinical.LayBanNhap(f.Id("LSA"),a)) with {KhongKeThuoc=true,LyDoKhongKeThuoc="FIXTURE"},a);clinical.HoanTatKham(f.Id("LSA"),c.DauVanTay,a);Invalid(()=>new BUS_DONTHUOC(f.Transaction).LuuDon(Request(f),a));});
        yield return("RX07: In chỉ đơn ký; bản chốt không đổi theo danh mục",f=>{var a=f.User("A");var b=new BUS_DONTHUOC(f.Transaction);var s=b.LuuDon(Request(f),a);Invalid(()=>b.LayBanInDon(s.Don.MaDT,a));s=b.XacNhanDon(s.Don.MaDT,s.DauVanTay,a);var name=s.CacDong[0].TenThuocChot;f.Execute("UPDATE dbo.HANG_HOA SET TenHH=N'FIXTURE tên đã đổi' WHERE MaHH=(SELECT MaHH FROM dbo.THUOC WHERE MaThuoc=@id)",new{id=s.CacDong[0].MaThuoc});Need(b.LayBanInDon(s.Don.MaDT,a).Nguon.CacDong[0].TenThuocChot==name,"In dùng tên danh mục mới");Invalid(()=>b.LuuDon(Update(s),a));});
    }
}
internal static class DrugFixtureQuery
{
    internal static string[] QueryDrugIds(this System.Data.IDbConnection db,System.Data.IDbTransaction tx,int count)=>Dapper.SqlMapper.Query<string>(db,"SELECT TOP(@count) t.MaThuoc FROM dbo.THUOC t JOIN dbo.HANG_HOA h ON h.MaHH=t.MaHH WHERE h.TrangThai=N'Đang hoạt động' ORDER BY t.MaThuoc",new{count},tx).ToArray();
}
